layout(std140) uniform f_buffer0 {
	vec4 f_cb0[19];
} _f_buffer0;
uniform highp sampler2D f_t0TEX_with_SMPf_s2;
uniform highp sampler2D f_t0;
uniform highp sampler2D f_t1TEX_with_SMPf_s4;
uniform highp sampler2D f_t1;
uniform highp sampler2D f_t2TEX_with_SMPf_s6;
uniform highp sampler2D f_t2;
uniform highp sampler2D f_t3TEX_with_SMPf_s5;
uniform highp sampler2D f_t3;
uniform highp sampler2D f_t4TEX_with_SMPf_s3;
uniform highp sampler2D f_t4;
uniform highp sampler2D f_t5TEX_with_SMPf_s0;
uniform highp sampler2D f_t5;
uniform highp sampler2D f_t6TEX_with_SMPf_s1;
uniform highp sampler2D f_t6;
in highp vec2 vs_TEXCOORD0;
in highp vec2 vs_TEXCOORD1;
in highp vec2 vs_TEXCOORD2;
in highp vec2 vs_TEXCOORD4;
in highp vec4 vs_TEXCOORD3;
in highp vec2 vs_TEXCOORD5;
in highp vec4 vs_TEXCOORD7;
in highp vec4 vs_COLOR0;
layout(location = 0) out highp vec4 SV_Target0;
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
vec3 u_xlat3;
vec3 u_xlat4;
vec3 u_xlat6;
float u_xlat12;
float u_xlat13;
void main()
{
    u_xlat0 = texture(f_t1TEX_with_SMPf_s4, vs_TEXCOORD2.xy);
    u_xlat1.x = u_xlat0.x * _f_buffer0.f_cb0[4].w;
    u_xlat1.y = u_xlat0.y * _f_buffer0.f_cb0[5].x;
    u_xlat0.xy = u_xlat1.xy + vs_TEXCOORD7.xy;
    u_xlat1 = texture(f_t4TEX_with_SMPf_s3, u_xlat0.xy);
    u_xlat0.xyw = (-u_xlat1.xyz) + _f_buffer0.f_cb0[4].yyy;
    u_xlat4.xyz = u_xlat0.zzz * abs(u_xlat0.xyw);
    u_xlat0.x = abs(u_xlat0.x) + -0.5;
    u_xlat4.xyz = u_xlat4.xyz * _f_buffer0.f_cb0[3].xyz;
    u_xlat4.xyz = u_xlat4.xyz * _f_buffer0.f_cb0[3].www;
    u_xlat0.yzw = u_xlat4.xyz * _f_buffer0.f_cb0[4].xxx;
    u_xlat1 = texture(f_t0TEX_with_SMPf_s2, vs_TEXCOORD0.xy);
    u_xlat0 = u_xlat0 * u_xlat1.xxxx;
    u_xlat2 = texture(f_t3TEX_with_SMPf_s5, vs_TEXCOORD4.xy);
    u_xlat2.xyz = (-u_xlat2.xyz) + _f_buffer0.f_cb0[9].yyy;
    u_xlat6.xyz = abs(u_xlat2.xyz) * _f_buffer0.f_cb0[8].xyz;
    u_xlat13 = abs(u_xlat2.x) + -0.5;
    u_xlat13 = u_xlat1.y * u_xlat13;
    u_xlat13 = u_xlat13 * _f_buffer0.f_cb0[9].w;
    u_xlat2.xyz = u_xlat6.xyz * _f_buffer0.f_cb0[8].www;
    u_xlat2.xyz = u_xlat2.xyz * _f_buffer0.f_cb0[9].xxx;
    u_xlat2.xyz = u_xlat1.yyy * u_xlat2.xyz;
    u_xlat2.xyz = u_xlat2.xyz * vs_TEXCOORD3.yyy;
    u_xlat3.xyz = u_xlat0.yzw * vs_TEXCOORD3.xxx + u_xlat2.xyz;
    u_xlat4.xyz = u_xlat0.yzw * vs_TEXCOORD3.xxx;
    u_xlat3.xyz = u_xlat3.xyz * vec3(0.5, 0.5, 0.5);
    u_xlat4.xyz = u_xlat4.xyz * u_xlat2.xyz + (-u_xlat3.xyz);
    u_xlat4.xyz = _f_buffer0.f_cb0[9].zzz * u_xlat4.xyz + u_xlat3.xyz;
    u_xlat2 = texture(f_t2TEX_with_SMPf_s6, vs_TEXCOORD5.xy);
    u_xlat2.xyz = (-u_xlat2.xyz) + _f_buffer0.f_cb0[14].zzz;
    u_xlat6.xyz = abs(u_xlat2.xyz) * _f_buffer0.f_cb0[13].xyz;
    u_xlat2.x = abs(u_xlat2.x) + -0.5;
    u_xlat2.x = u_xlat1.z * u_xlat2.x;
    u_xlat13 = u_xlat2.x * _f_buffer0.f_cb0[15].x + u_xlat13;
    u_xlat2.xyz = u_xlat6.xyz * _f_buffer0.f_cb0[13].www;
    u_xlat2.xyz = u_xlat2.xyz * _f_buffer0.f_cb0[14].xxx;
    u_xlat2.xyz = u_xlat1.zzz * u_xlat2.xyz;
    u_xlat3.xyz = u_xlat2.xyz * vs_TEXCOORD3.zzz + u_xlat4.xyz;
    u_xlat2.xyz = u_xlat2.xyz * vs_TEXCOORD3.zzz;
    u_xlat3.xyz = u_xlat3.xyz * vec3(0.5, 0.5, 0.5);
    u_xlat4.xyz = u_xlat4.xyz * u_xlat2.xyz + (-u_xlat3.xyz);
    u_xlat4.xyz = _f_buffer0.f_cb0[14].www * u_xlat4.xyz + u_xlat3.xyz;
    u_xlat0.x = u_xlat0.x * _f_buffer0.f_cb0[4].z + u_xlat13;
    u_xlat2.xy = _f_buffer0.f_cb0[18].yz * u_xlat0.xx + vs_TEXCOORD0.xy;
    u_xlat2 = texture(f_t5TEX_with_SMPf_s0, u_xlat2.xy);
    u_xlat0.xyz = u_xlat4.xyz + u_xlat2.xyz;
    u_xlat0.xyz = _f_buffer0.f_cb0[17].zzz * _f_buffer0.f_cb0[17].www + u_xlat0.xyz;
    u_xlat0.xyz = (-u_xlat2.xyz) + u_xlat0.xyz;
    u_xlat12 = u_xlat1.y + u_xlat1.x;
    u_xlat12 = u_xlat1.z + u_xlat12;
#ifdef UNITY_ADRENO_ES3
    u_xlat12 = min(max(u_xlat12, 0.0), 1.0);
#else
    u_xlat12 = clamp(u_xlat12, 0.0, 1.0);
#endif
    u_xlat0.xyz = vec3(u_xlat12) * u_xlat0.xyz + u_xlat2.xyz;
#ifdef UNITY_ADRENO_ES3
    u_xlat0.xyz = min(max(u_xlat0.xyz, 0.0), 1.0);
#else
    u_xlat0.xyz = clamp(u_xlat0.xyz, 0.0, 1.0);
#endif
    u_xlat1.xyz = u_xlat0.xyz + vec3(0.150000006, 0.150000006, 0.150000006);
    u_xlat1.xyz = u_xlat1.xyz * vs_COLOR0.xyz;
    u_xlat0.xyz = min(u_xlat0.xyz, u_xlat1.xyz);
    u_xlat1 = texture(f_t6TEX_with_SMPf_s1, vs_TEXCOORD1.xy);
    u_xlat0.w = 1.0;
    SV_Target0 = u_xlat0 * u_xlat1;
    return;
}
